<script setup lang="ts">
import {ref, onMounted, nextTick} from 'vue'
import {splitTarget, joinTarget} from './proxy-address'
import {readAPIResponse} from './api-response'
import DDNSManager from './DDNSManager.vue'
import CertificateManager from './CertificateManager.vue'
type Route={id:string;name?:string;domain:string;port:number;scheme:string;upstream:string;certificate_id:string;enabled:boolean}
type Cert={id:string;domains:string[];mode:string;email:string;staging:boolean;account_id?:string;renew_before_days?:number}
type Config={revision:number;routes:Route[];certificates:Cert[]}
const token=ref(''),logged=ref(false),busy=ref(false),message=ref(''),tab=ref('routes'),status=ref<{proxy?:{running:boolean;modules?:string[]}}>({})
const config=ref<Config>({revision:0,routes:[],certificates:[]})
const route=ref<Route>(newRoute()),cert=ref<Cert>(newCert()),domains=ref(''),editing=ref(false)
const target=ref(splitTarget(route.value.upstream))
const editor=ref<HTMLDialogElement>(), viewer=ref<HTMLDialogElement>(), deletion=ref<HTMLDialogElement>()
const dnsAccounts=ref<{id:string;name:string;provider:string}[]>([]),certificateProviders=ref<string[]>([])
const copyMessage=ref('')
const modalError=ref(''), viewError=ref(''), viewBusy=ref(false), viewTab=ref<'draft'|'applied'>('draft')
const caddyView=ref<{draft:unknown;applied:unknown}>({draft:null,applied:null})
const pendingDelete=ref<{kind:'routes'|'certificates';key:string;name:string}>()
function closeEditor(){if(!busy.value)editor.value?.close()}
async function openEditor(){modalError.value=''; await nextTick(); editor.value?.showModal();editor.value?.querySelector<HTMLElement>('select,input')?.focus()}
async function add(){if(tab.value==='certificates')await action(loadDNSAccounts);editing.value=false;route.value=newRoute();target.value=splitTarget(route.value.upstream);cert.value=newCert();domains.value='';openEditor()}
function askDelete(kind:'routes'|'certificates',key:string,name:string){pendingDelete.value={kind,key,name};modalError.value='';deletion.value?.showModal()}
async function showCaddy(){viewer.value?.showModal();await loadCaddy()}
async function loadCaddy(){copyMessage.value='';viewBusy.value=true;viewError.value='';try{const view=await api<{draft:unknown;applied:unknown;draft_error?:string}>('/proxy/config');caddyView.value=view;if(view.draft_error)viewError.value=view.draft_error}catch(e){caddyView.value={draft:null,applied:null};viewError.value=e instanceof Error?e.message:String(e)}finally{viewBusy.value=false}}
async function copyConfig(){try{await navigator.clipboard.writeText(JSON.stringify(caddyView.value[viewTab.value],null,2));copyMessage.value='配置已复制'}catch{viewError.value='浏览器不支持复制，请选择配置文本手动复制。'}}
function logout(){logged.value=false;token.value='';sessionStorage.removeItem('netlite-token')}
function id(){return Array.from(crypto.getRandomValues(new Uint8Array(8)),b=>b.toString(16).padStart(2,'0')).join('')}
function newRoute():Route{return {id:id(),name:'',domain:'',port:18080,scheme:'http',upstream:'http://127.0.0.1:8080',certificate_id:'',enabled:true}}
function newCert():Cert{return {id:id(),domains:[],renew_before_days:0,mode:'internal',email:'',account_id:'',staging:true}}
async function api<T>(url:string,method='GET',body?:unknown):Promise<T>{const r=await fetch('/api'+url,{method,headers:{Authorization:'Bearer '+token.value,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});return readAPIResponse<T>(r,url)}
async function download(path:string,name:string){const response=await fetch('/api'+path,{headers:{Authorization:'Bearer '+token.value}});if(!response.ok)throw new Error('证书文件尚未就绪');const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
async function action(fn:()=>Promise<void>){busy.value=true;message.value='';try{await fn()}catch(e){message.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function refresh(){status.value=await api('/status')}
async function login(){await action(async()=>{config.value=await api('/config');logged.value=true;sessionStorage.setItem('netlite-token',token.value);await refresh();await loadDNSAccounts()})}
async function save(){config.value=await api('/config','PUT',config.value);message.value='配置已保存。证书自动申请和续期；代理规则需点击「应用到代理」生效。'}
function editRoute(x:Route){route.value={...x};target.value=splitTarget(x.upstream);editing.value=true;openEditor()}
async function loadDNSAccounts(){const a=await api<{accounts:{id:string;name:string;provider:string}[]}>('/dns/accounts');dnsAccounts.value=a.accounts;const c=await api<{certificate_providers:string[]}>('/dns-capabilities');certificateProviders.value=c.certificate_providers}
async function editCert(x:Cert){await action(loadDNSAccounts);cert.value={...x,domains:[...x.domains]};domains.value=x.domains.join(', ');editing.value=true;openEditor()}
function upsert<T extends {id:string}>(list:T[],x:T){const i=list.findIndex(a=>a.id===x.id);if(i<0)list.push(x);else list[i]=x}
async function submitRoute(){modalError.value='';try{route.value.upstream=joinTarget(target.value)}catch(e){modalError.value=e instanceof Error?e.message:String(e);return}await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));upsert(config.value.routes,{...route.value});try{await save();route.value=newRoute();editing.value=false;editor.value?.close()}catch(e){config.value=old;modalError.value=e instanceof Error?e.message:String(e);throw e}})}
async function submitCert(){modalError.value='';await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));upsert(config.value.certificates,{...cert.value,account_id:cert.value.mode==='dns'?cert.value.account_id:'',domains:domains.value.split(/[,\s]+/).filter(Boolean)});try{await save();cert.value=newCert();domains.value='';editing.value=false;editor.value?.close()}catch(e){config.value=old;modalError.value=e instanceof Error?e.message:String(e);throw e}})}
async function remove(kind:'routes'|'certificates',key:string){await action(async()=>{const old=JSON.parse(JSON.stringify(config.value));config.value[kind]=config.value[kind].filter(x=>x.id!==key) as Route[]&Cert[];try{await save();deletion.value?.close()}catch(e){config.value=old;modalError.value=e instanceof Error?e.message:String(e);throw e}})}
onMounted(()=>{token.value=sessionStorage.getItem('netlite-token')||'';if(token.value)login()})
</script>
<template>
 <main><header><div class="brand"><span class="logo">N</span><div><h1>NetLite</h1><p>让网络管理轻一点</p></div></div><span class="badge">0.1 · 本地管理</span></header>
 <section v-if="!logged" class="login card"><h2>进入管理面板</h2><p>输入应用私有数据目录中 admin-token 文件的管理令牌。</p><form @submit.prevent="login"><label>管理令牌<input v-model="token" type="password" autocomplete="current-password" required></label><button :disabled="busy">登录</button></form></section>
 <template v-else>
 <div class="toolbar"><span :class="['dot',status.proxy?.running?'on':'']"></span><span>Caddy {{status.proxy?.running?'运行中':'未运行'}}</span><span class="muted">配置版本 {{config.revision}}</span><button class="secondary" :disabled="busy" @click="showCaddy">查看 Caddy 配置</button><button class="secondary" :disabled="busy" @click="action(refresh)">刷新状态</button><button class="secondary" :disabled="busy" @click="action(async()=>{await api('/proxy/validate','POST');message='配置校验通过'})">校验配置</button><button :disabled="busy" @click="action(async()=>{const r=await api<{applied_revision:number}>('/proxy/apply','POST');message='已应用版本 '+r.applied_revision+'；已加载 NetLite 管理的证书';await refresh()})">应用到代理</button></div>
 <nav><button v-for="[key,title] in [['routes','反向代理'],['certificates','HTTPS 证书'],['ddns','动态 DNS'],['dnsaccounts','DNS 账号']]" :class="{active:tab===key}" @click="tab=key!;editing=false">{{title}}</button><button class="logout" @click="logout">退出</button></nav>
 <div v-if="tab==='routes'" class="content-list"><section class="card"><div class="section-head"><h2>代理规则</h2><button :disabled="busy" @click="add">＋ 添加代理</button></div><p class="muted">按域名和端口访问内网服务，支持 WebSocket。</p><p v-if="!config.routes.length" class="empty">还没有规则，点击「添加代理」开始。</p><div v-if="config.routes.length" class="proxy-table-wrap" tabindex="0" aria-label="代理规则表格，窄屏可左右滚动"><table class="proxy-table"><colgroup><col class="name-col"><col class="protocol-col"><col class="address-col"><col class="port-col"><col class="protocol-col"><col class="address-col"><col class="port-col"><col class="status-col"><col class="actions-col"></colgroup><thead><tr class="group-heading"><th scope="col" rowspan="2">名称 / 备注</th><th scope="colgroup" colspan="3">访问端</th><th scope="colgroup" colspan="3" class="target-start">目标端</th><th scope="col" rowspan="2">状态</th><th scope="col" rowspan="2" class="actions-heading">操作</th></tr><tr><th scope="col">协议</th><th scope="col">域名</th><th scope="col">端口</th><th scope="col" class="target-start">协议</th><th scope="col">地址</th><th scope="col">端口</th></tr></thead><tbody><tr v-for="r in config.routes" :key="r.id"><td><span :class="['route-name',{unnamed:!r.name}]">{{r.name || '—'}}</span></td><td><span :class="['protocol-badge',r.scheme]">{{r.scheme.toUpperCase()}}</span></td><td><strong class="domain-name">{{r.domain}}</strong></td><td><span class="port-number">{{r.port}}</span></td><td class="target-start"><span :class="['protocol-badge',splitTarget(r.upstream).scheme]">{{splitTarget(r.upstream).scheme.toUpperCase()}}</span></td><td><span class="target-address">{{splitTarget(r.upstream).address}}</span></td><td><span class="port-number target-port">{{splitTarget(r.upstream).port}}</span></td><td><span :class="['route-status',r.enabled?'enabled':'disabled']">{{r.enabled?'启用':'停用'}}</span></td><td><div class="small-actions"><button class="secondary" :disabled="busy" :aria-label="'编辑 '+r.domain+':'+r.port" @click="editRoute(r)">编辑</button><button class="danger" :disabled="busy" :aria-label="'删除 '+r.domain+':'+r.port" @click="askDelete('routes',r.id,(r.name?r.name+' · ':'')+r.domain+':'+r.port)">删除</button></div></td></tr></tbody></table></div></section>
 </div>
 <CertificateManager v-if="tab==='certificates'" :certificates="config.certificates" :api="api" :download="download" @add="add" @edit="editCert" @remove="c=>askDelete('certificates',c.id,c.domains.join(', '))" />
 <DDNSManager v-if="tab==='ddns'" :api="api" @manage-accounts="tab='dnsaccounts'" />
 <DDNSManager v-if="tab==='dnsaccounts'" :api="api" mode="accounts" />
 <dialog ref="editor" class="editor-dialog" aria-labelledby="editor-title" @cancel="busy && $event.preventDefault()"><section v-if="tab==='routes'"><div class="dialog-head"><h2 id="editor-title">{{editing?'编辑':'添加'}}代理</h2><button type="button" class="icon-button" aria-label="关闭" :disabled="busy" @click="closeEditor">×</button></div><form @submit.prevent="submitRoute"><label>名称 / 备注（选填）<input v-model="route.name" placeholder="例如：家庭相册、下载工具"></label><fieldset class="endpoint-fields"><legend>访问端</legend><div class="endpoint-row"><label>访问协议<select v-model="route.scheme"><option value="http">HTTP</option><option value="https">HTTPS</option></select></label><label>访问域名<input v-model="route.domain" placeholder="app.example.com" required></label><label>访问端口<input v-model.number="route.port" type="number" min="1024" max="65535" required></label></div></fieldset><fieldset class="endpoint-fields"><legend>目标端</legend><div class="endpoint-row"><label>目标协议<select v-model="target.scheme"><option value="http">HTTP</option><option value="https">HTTPS</option></select></label><label>目标地址<input v-model="target.address" placeholder="192.168.1.10 或 service.local" required></label><label>目标端口<input v-model.number="target.port" type="number" min="1" max="65535" required></label></div><p class="muted">目标地址填写实际提供服务的 IP 或域名。127.0.0.1 表示运行 NetLite 的这台设备。</p></fieldset><label v-if="route.scheme==='https'">证书策略<select v-model="route.certificate_id" required><option value="">请选择覆盖该域名的证书</option><option v-for="c in config.certificates" :value="c.id">{{c.domains.join(', ')}}</option></select></label><label class="check"><input v-model="route.enabled" type="checkbox">启用规则</label><p v-if="modalError" class="form-error" role="alert">{{modalError}}</p><div class="dialog-actions"><button type="button" class="secondary" :disabled="busy" @click="closeEditor">取消</button><button :disabled="busy">保存规则</button></div></form></section><section v-if="tab==='certificates'"><div class="dialog-head"><h2 id="editor-title">{{editing?'编辑':'添加'}}证书策略</h2><button type="button" class="icon-button" aria-label="关闭" :disabled="busy" @click="closeEditor">×</button></div><form @submit.prevent="submitCert"><label>域名（逗号分隔）<input v-model="domains" placeholder="*.example.com, example.com" required></label><label>签发方式<select v-model="cert.mode"><option value="internal">内部 CA（本地测试）</option><option value="acme">ACME（HTTP-01）</option><option value="dns">DNS-01（引用 DNS 账号）</option></select></label><label v-if="cert.mode!=='internal'">联系邮箱<input v-model="cert.email" type="email" required></label><template v-if="cert.mode==='dns'"><label>DNS 账号<select v-model="cert.account_id" required><option value="">请选择 DNS 账号</option><option v-for="a in dnsAccounts.filter(a=>certificateProviders.includes(a.provider))" :key="a.id" :value="a.id">{{a.name}} · {{a.provider}}</option></select></label><p class="muted">账号与 DDNS 共用，证书验证需要 TXT 查询、创建和删除权限，无需启用 DDNS。</p><button type="button" class="secondary" @click="closeEditor();tab='dnsaccounts'">管理 DNS 账号</button></template><label>提前续期天数（0 表示自动）<input v-model.number="cert.renew_before_days" type="number" min="0" max="60"></label><label v-if="cert.mode!=='internal'" class="check"><input v-model="cert.staging" type="checkbox">使用 Let's Encrypt 测试 CA</label><p class="muted">保存后自动申请并管理续期。HTTP-01 需要公网 80 映射到独立验证端口 18082；DNS-01 无需开放验证端口。</p><p v-if="modalError" class="form-error" role="alert">{{modalError}}</p><div class="dialog-actions"><button type="button" class="secondary" :disabled="busy" @click="closeEditor">取消</button><button :disabled="busy">保存策略</button></div></form></section></dialog>
 <dialog ref="deletion" class="delete-dialog" aria-labelledby="delete-title" @cancel="busy && $event.preventDefault()"><div class="dialog-head"><h2 id="delete-title">确认删除</h2></div><p>确定删除「{{pendingDelete?.name}}」？</p><p class="muted">删除后需应用到代理，反代与证书的变更才会生效。</p><p v-if="modalError" class="form-error" role="alert">{{modalError}}</p><div class="dialog-actions"><button class="secondary" :disabled="busy" @click="deletion?.close()">取消</button><button class="danger" :disabled="busy" @click="pendingDelete && remove(pendingDelete.kind,pendingDelete.key)">确认删除</button></div></dialog>
 <dialog ref="viewer" class="config-dialog" aria-labelledby="config-title"><div class="dialog-head"><h2 id="config-title">Caddy 配置</h2><button class="icon-button" aria-label="关闭配置" @click="viewer?.close()">×</button></div><p class="muted">草稿由当前保存的规则生成；已应用配置为最近成功应用后保存的配置。凭据已隐藏。</p><div class="config-toolbar"><button :class="['secondary',{selected:viewTab==='draft'}]" @click="viewTab='draft'">配置草稿</button><button :class="['secondary',{selected:viewTab==='applied'}]" @click="viewTab='applied'">已应用配置</button><button class="secondary" :disabled="viewBusy" @click="loadCaddy">刷新</button><button class="secondary" :disabled="viewBusy||!caddyView[viewTab]" @click="copyConfig">复制配置</button></div><p v-if="copyMessage" class="muted" role="status">{{copyMessage}}</p><p v-if="viewError" class="form-error" role="alert">{{viewError}}</p><p v-if="viewBusy" class="empty">正在加载配置…</p><pre v-else-if="caddyView[viewTab]" tabindex="0">{{JSON.stringify(caddyView[viewTab],null,2)}}</pre><p v-else-if="!viewError" class="empty">{{viewTab==='applied'?'尚未应用过配置。':'暂无配置草稿。'}}</p><div class="dialog-actions"><button @click="viewer?.close()">关闭</button></div></dialog>
 </template><div v-if="message" class="message" role="status">{{message}}</div><footer>独立代理进程 · SQLite 配置 · 不接管系统 Web 服务</footer></main>
</template>

